import re
from pathlib import Path
from typing import Optional

from ci.praktika.git import Git
from ci.praktika.info import Info
from ci.praktika.utils import Shell

FILE_WITH_VERSION_PATH = "./cmake/autogenerated_versions.txt"

# Canonical layout of cmake/autogenerated_versions.txt as committed to the repo.
VERSIONS_TEMPLATE = """\
# This variables autochanged by ci/jobs/create_release.py:

# NOTE: VERSION_REVISION has nothing common with DBMS_TCP_PROTOCOL_VERSION,
# only DBMS_TCP_PROTOCOL_VERSION should be incremented on protocol changes.
SET(VERSION_REVISION {revision})
SET(VERSION_MAJOR {major})
SET(VERSION_MINOR {minor})
SET(VERSION_PATCH {patch})
SET(VERSION_GITHASH {githash})
SET(VERSION_DESCRIBE {describe})
SET(VERSION_STRING {string})
# end of autochange
"""


class VersionType:
    NEW = "new"
    TESTING = "testing"
    PRESTABLE = "prestable"
    STABLE = "stable"
    LTS = "lts"
    VALID = {NEW, TESTING, PRESTABLE, STABLE, LTS}


def _read_versions() -> dict:
    versions = {}
    for line in Path(FILE_WITH_VERSION_PATH).read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line.startswith("SET("):
            continue
        name, value = line[4:-1].split(maxsplit=1)
        name = name.removeprefix("VERSION_").lower()
        try:
            value = int(value)
        except ValueError:
            pass
        versions[name] = value
    return versions


class ClickHouseVersion:
    """The ClickHouse version.

    As an instance it is a mutable version model used to bump and render the
    release version (see `get_version_from_repo`). Its class methods read and
    write `cmake/autogenerated_versions.txt` and derive the CI build version.
    """

    _TAG_PATTERN = re.compile(
        r"\Av\d{2}([.][1-9]\d*){3}-(new|testing|prestable|stable|lts)\Z"
    )
    _TWEAK_DEFAULT = 1

    def __init__(self, major, minor, patch, revision, tweak=None):
        self._major = int(major)
        self._minor = int(minor)
        self._patch = int(patch)
        self._revision = int(revision)
        self._tweak = int(tweak) if tweak is not None else self._TWEAK_DEFAULT
        self._description = ""
        self._describe = ""

    def bump(self) -> "ClickHouseVersion":
        """Bump minor version (or wrap to next major when minor reaches 12)."""
        if self._minor < 12:
            self._minor += 1
        else:
            self._major += 1
            self._minor = 1
        self._revision += 1
        self._patch = 1
        self._tweak = 1
        return self

    def bump_patch(self) -> "ClickHouseVersion":
        self._revision += 1
        self._patch += 1
        self._tweak = 1
        return self

    def reset_tweak(self) -> "ClickHouseVersion":
        self._tweak = 1
        return self

    def with_description(self, version_type: str) -> "ClickHouseVersion":
        if version_type not in VersionType.VALID:
            raise ValueError(f"version type {version_type!r} not in {VersionType.VALID}")
        self._description = version_type
        self._describe = f"v{self.string}-{version_type}"
        return self

    def get_stable_release_type(self) -> str:
        return VersionType.LTS if self._minor % 5 == 3 else VersionType.STABLE

    def has_newer_release_tag(self) -> bool:
        """Whether the release branch already has a release tag with a higher
        version than this one.

        Scans all `vX.Y.*` tags on the branch (by name, so it sees the whole
        branch regardless of what is reachable from the current commit) and
        ignores the `-new` branch-cut tag.
        """
        branch_tags = Shell.get_output(
            f"git tag --list 'v{self._major}.{self._minor}.*'"
        ).split()
        for tag in branch_tags:
            if tag.endswith("-new"):
                continue
            try:
                other = _version_from_tag(tag)
            except Exception:
                continue
            if self < other:
                return True
        return False

    @property
    def major(self) -> int:
        return self._major

    @property
    def minor(self) -> int:
        return self._minor

    @property
    def patch(self) -> int:
        return self._patch

    @property
    def revision(self) -> int:
        return self._revision

    @property
    def tweak(self) -> int:
        return self._tweak

    @tweak.setter
    def tweak(self, value: int) -> None:
        self._tweak = value

    @property
    def description(self) -> str:
        return self._description

    @property
    def describe(self) -> str:
        return self._describe

    @property
    def string(self) -> str:
        return f"{self._major}.{self._minor}.{self._patch}.{self._tweak}"

    def as_dict(self) -> dict:
        return {
            "revision": self._revision,
            "major": self._major,
            "minor": self._minor,
            "patch": self._patch,
            "tweak": self._tweak,
            "githash": Shell.get_output("git rev-parse HEAD") or "0" * 40,
            "describe": self._describe,
            "string": self.string,
        }

    def __eq__(self, other) -> bool:
        if not isinstance(other, ClickHouseVersion):
            return NotImplemented
        return (self._major, self._minor, self._patch, self._tweak) == (
            other._major, other._minor, other._patch, other._tweak
        )

    def __lt__(self, other) -> bool:
        if not isinstance(other, ClickHouseVersion):
            return NotImplemented
        return (self._major, self._minor, self._patch, self._tweak) < (
            other._major, other._minor, other._patch, other._tweak
        )

    # --- reading / writing cmake/autogenerated_versions.txt ------------------

    @classmethod
    def get_release_version_as_dict(cls):
        versions = _read_versions()
        return {
            "major": versions["major"],
            "minor": versions["minor"],
            "patch": versions["patch"],
            "revision": versions["revision"],
            "githash": versions["githash"],
            "describe": versions["describe"],
            "string": versions["string"],
        }

    @classmethod
    def get_current_version_as_dict(cls):
        """Version stamped into the binary during a CI build.

        Unlike `get_version_from_repo` (which derives the tweak from git tags
        for the release process), this derives the tweak and type from the CI
        `Info` context.
        """
        version = cls.get_release_version_as_dict()
        info = Info()
        if info.pr_number != 0:
            # Pin tweak in PRs: it is meaningless there and otherwise diverges
            # across re-runs for the same HEAD, yielding two versions at one
            # artifact prefix (see commit message).
            tweak = 1
        else:
            try:
                tweak = int(
                    Shell.get_output(
                        f"git rev-list --count --first-parent {version['githash']}..HEAD",
                        verbose=True,
                    )
                )
            except (ValueError, Exception):
                # Shallow checkout or other error
                tweak = 1
        version_type = "testing"
        if info.pr_number == 0 and bool(
            re.match(r"^\d{2}\.\d+$", info.git_branch.removeprefix("release/"))
        ):
            if version["minor"] % 5 == 3:
                version_type = "lts"
            else:
                version_type = "stable"
        version_string = (
            f'{version["major"]}.{version["minor"]}.{version["patch"]}.{tweak}'
        )
        version_description = f"v{version_string}-{version_type}"
        version["githash"] = info.sha
        version["tweak"] = tweak
        version["describe"] = version_description
        version["string"] = version_string
        return version

    @classmethod
    def set_binary_version(cls, version_dict=None):
        version_dict = version_dict or cls.get_current_version_as_dict()
        Path(FILE_WITH_VERSION_PATH).write_text(
            VERSIONS_TEMPLATE.format_map(version_dict), encoding="utf-8"
        )

    @staticmethod
    def store_version_data_in_ci_pipeline(version):
        print(f"Store version in pipeline kv data: [version={version}]")
        Info().store_kv_data("version", version)


def _version_from_tag(tag: str) -> ClickHouseVersion:
    tag_body, description = tag[1:].split("-", 1)
    parts = tag_body.split(".")
    v = ClickHouseVersion(parts[0], parts[1], parts[2], -1, int(parts[3]))
    v.with_description(description)
    return v


def get_version_from_repo(git: Optional[Git] = None) -> ClickHouseVersion:
    v = _read_versions()
    version = ClickHouseVersion(v["major"], v["minor"], v["patch"], v["revision"])
    if git is not None and git.latest_tag:
        latest = _version_from_tag(git.latest_tag)
        if latest.description == VersionType.NEW and version < latest:
            version.tweak = git.tweak_to_new
        else:
            version.tweak = git.tweak
    return version


def update_cmake_version(
    version: ClickHouseVersion, preserve_sha: bool = False
) -> None:
    version_dict = version.as_dict()
    if preserve_sha:
        version_dict["githash"] = _read_versions().get("githash", "0" * 40)
    Path(FILE_WITH_VERSION_PATH).write_text(
        VERSIONS_TEMPLATE.format_map(version_dict), encoding="utf-8"
    )


if __name__ == "__main__":
    # test;
    print(ClickHouseVersion.get_current_version_as_dict())
